import { describe, expect, it } from 'vitest';
import {
  canonicalizeBrowserRelayProof,
  createBrowserRelayProof,
  deriveBrowserRelayKeyId,
  verifyBrowserRelayProof,
} from '../src/browser-relay-auth-v2.js';

const KEY = Buffer.from('000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f', 'hex');
const FIELDS = {
  keyId: 'Yw3NKWbEM2aRElRIu7JbT_',
  instanceId: 'EREREREREREREREREREREQ',
  sessionId: 'IiIiIiIiIiIiIiIiIiIiIg',
  clientNonce: 'MzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzM',
  serverNonce: 'REREREREREREREREREREREREREREREREREREREREREQ',
  issuedAtMs: 1_786_123_456_000,
  expiresAtMs: 1_786_123_466_000,
  role: 'extension',
  transport: 'websocket',
  method: 'GET',
  resource: '/extension?profile=chrome',
  flow: 'extension',
} as const;

describe('Browser Relay Authentication v2 common vectors', () => {
  it('matches the frozen Node/WebCrypto vector shared with OpenClaw', () => {
    expect(deriveBrowserRelayKeyId(KEY)).toBe('Yw3NKWbEM2aRElRIu7JbT_');
    expect(canonicalizeBrowserRelayProof('server', FIELDS).toString('utf8')).toBe(
      '["openclaw.browser-relay.auth",2,"server","Yw3NKWbEM2aRElRIu7JbT_","EREREREREREREREREREREQ","IiIiIiIiIiIiIiIiIiIiIg","MzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzMzM","REREREREREREREREREREREREREREREREREREREREREQ",1786123456000,1786123466000,"extension","websocket","GET","/extension?profile=chrome","extension"]'
    );
    const serverProof = createBrowserRelayProof(KEY, 'server', FIELDS);
    const clientProof = createBrowserRelayProof(KEY, 'client', FIELDS);
    expect(serverProof).toBe('ynhaAA_l2HkOGXQ8DvIWfzWwwGjDcV93aumHNe_NM-Q');
    expect(clientProof).toBe('Rl8TStMYlPLxJPDYwSe__mtEjgMf1C4TM-ZN6sUipZ4');
    expect(createBrowserRelayProof(KEY, 'accept', FIELDS, clientProof)).toBe(
      '1R5MpHs6qnAdc0_X6vKBwj91tlRoWfNuGXaNfSD7VnI'
    );
  });

  it('uses constant-length proof validation and binds every canonical field', () => {
    const proof = createBrowserRelayProof(KEY, 'server', FIELDS);
    expect(verifyBrowserRelayProof(KEY, 'server', FIELDS, proof)).toBe(true);
    for (const [key, value] of Object.entries(FIELDS)) {
      const altered = { ...FIELDS, [key]: typeof value === 'number' ? value + 1 : `${value}x` };
      expect(verifyBrowserRelayProof(KEY, 'server', altered, proof), key).toBe(false);
    }
    expect(verifyBrowserRelayProof(KEY, 'server', FIELDS, `${proof.slice(0, -1)}A`)).toBe(false);
    expect(verifyBrowserRelayProof(KEY, 'server', FIELDS, 'not-a-proof')).toBe(false);
  });
});

import { describe, expect, it, vi } from 'vitest';

process.env.MCPORTER_DISABLE_AUTORUN = '1';
const cliModulePromise = import('../src/cli.js');

const baseDefinition = {
  name: 'adhoc-server',
  command: { kind: 'http' as const, url: new URL('https://example.com/mcp') },
  source: { kind: 'local' as const, path: '<adhoc>' },
};

describe('handleAuth retry logic', () => {
  it('retries once when the first attempt is unauthorized', async () => {
    const { handleAuth } = await cliModulePromise;
    const listTools = vi
      .fn()
      .mockRejectedValueOnce(new Error('SSE error: Non-200 status code (401)'))
      .mockResolvedValueOnce([{ name: 'ok' }]);
    const runtime = {
      registerDefinition: vi.fn(),
      getDefinition: vi.fn().mockReturnValue(baseDefinition),
      listTools,
    } as unknown as Awaited<ReturnType<(typeof import('../src/runtime.js'))['createRuntime']>>;

    await expect(handleAuth(runtime, ['adhoc-server'])).resolves.toBeUndefined();
    expect(listTools).toHaveBeenCalledTimes(2);
  });

  it('throws after the second unauthorized attempt', async () => {
    const { handleAuth } = await cliModulePromise;
    const listTools = vi.fn().mockRejectedValue(new Error('SSE error: Non-200 status code (401)'));
    const runtime = {
      registerDefinition: vi.fn(),
      getDefinition: vi.fn().mockReturnValue(baseDefinition),
      listTools,
    } as unknown as Awaited<ReturnType<(typeof import('../src/runtime.js'))['createRuntime']>>;

    await expect(handleAuth(runtime, ['adhoc-server'])).rejects.toThrow(/Failed to authorize/);
    expect(listTools).toHaveBeenCalledTimes(2);
  });
});

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import type { ServerDefinition } from '../src/config.js';
import { getOAuthVaultPath, vaultKeyForDefinition } from '../src/oauth-vault.js';
import { sealVaultSecret, vaultSecretKid } from '../src/oauth-vault-encryption.js';
import { applyCachedAuthIfAvailable } from '../src/runtime/cached-auth.js';

const definition: ServerDefinition = {
  name: 'enc',
  command: { kind: 'http', url: new URL('https://example.com/mcp') },
  auth: 'oauth',
};
const logger = { info() {}, warn() {}, error() {}, debug: vi.fn() };
let dir: string;

beforeEach(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), 'mcporter-cached-auth-'));
  vi.stubEnv('XDG_DATA_HOME', path.join(dir, 'data'));
  const key = vaultKeyForDefinition(definition);
  const sealed = await sealVaultSecret(
    'access-enc',
    vaultSecretKid(key, ['tokens', 'access_token']),
    'cached-auth-password-0123456789ab'
  );
  await fs.mkdir(path.dirname(getOAuthVaultPath()), { recursive: true });
  await fs.writeFile(
    getOAuthVaultPath(),
    JSON.stringify({
      version: 2,
      entries: {
        [key]: {
          serverName: 'enc',
          serverUrl: 'https://example.com/mcp',
          updatedAt: 'now',
          tokens: { access_token: sealed, token_type: 'Bearer' },
        },
      },
    }),
    'utf8'
  );
});
afterEach(async () => {
  vi.unstubAllEnvs();
  await fs.rm(dir, { recursive: true, force: true });
});

it('surfaces the vault error instead of silently starting an auth flow', async () => {
  await expect(applyCachedAuthIfAvailable(definition, logger, true)).rejects.toMatchObject({
    name: 'VaultEncryptionError',
    code: 'password_missing',
  });
  expect(logger.debug).not.toHaveBeenCalledWith(expect.stringContaining('Failed to read cached OAuth token'));
});

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import type { ServerDefinition } from '../src/config.js';
import { expandHome } from '../src/env.js';
import { clearOAuthCaches } from '../src/oauth-persistence.js';

const mkDef = (name: string, tokenCacheDir?: string): ServerDefinition => ({
  name,
  description: `${name} server`,
  command: { kind: 'http', url: new URL('https://example.com/mcp') },
  auth: 'oauth',
  tokenCacheDir,
});

describe('clearOAuthCaches tokenCacheDir containment', () => {
  const originalEnv = { ...process.env };
  const tempRoots: string[] = [];
  let homedirSpy!: ReturnType<typeof vi.spyOn>;
  let hasSpy = false;

  afterEach(async () => {
    if (hasSpy) {
      homedirSpy.mockRestore();
      hasSpy = false;
    }
    process.env = { ...originalEnv };
    await Promise.all(tempRoots.splice(0).map((dir) => fs.rm(dir, { recursive: true, force: true })));
  });

  async function isolateHome(): Promise<string> {
    const tmp = await fs.mkdtemp(path.join(os.tmpdir(), 'mcporter-oauth-jail-'));
    tempRoots.push(tmp);
    const home = path.join(tmp, 'home');
    await fs.mkdir(home, { recursive: true });
    homedirSpy = vi.spyOn(os, 'homedir').mockReturnValue(home);
    hasSpy = true;
    // The vault honors XDG_* dirs (src/paths.ts), which the os.homedir() spy does
    // not cover — without this, tests read and write the developer's real vault.
    delete process.env.XDG_CONFIG_HOME;
    delete process.env.XDG_DATA_HOME;
    delete process.env.XDG_STATE_HOME;
    delete process.env.XDG_CACHE_HOME;
    process.env.HOME = home;
    process.env.USERPROFILE = home;
    return home;
  }

  it('keeps a canary in tokenCacheDir after clearing known credential files', async () => {
    const home = await isolateHome();
    const cacheDir = path.join(home, 'token-cache');
    await fs.mkdir(cacheDir, { recursive: true });
    const canaryPath = path.join(cacheDir, 'IMPORTANT.txt');
    const tokensPath = path.join(cacheDir, 'tokens.json');
    await fs.writeFile(canaryPath, 'do-not-delete');
    await fs.writeFile(tokensPath, JSON.stringify({ access_token: 'cached', token_type: 'Bearer' }));

    await clearOAuthCaches(mkDef('jail-cache', cacheDir), undefined, 'all');

    await expect(fs.readFile(canaryPath, 'utf8')).resolves.toBe('do-not-delete');
    await expect(fs.stat(cacheDir).then((stat) => stat.isDirectory())).resolves.toBe(true);
    await expect(fs.access(tokensPath)).rejects.toThrow();
  });

  it('does not wipe a fake home when tokenCacheDir is the homedir', async () => {
    const home = await isolateHome();
    const canaryPath = path.join(home, 'IMPORTANT.txt');
    const notesPath = path.join(home, 'Documents', 'notes.txt');
    await fs.mkdir(path.dirname(notesPath), { recursive: true });
    await fs.writeFile(canaryPath, 'keep-home');
    await fs.writeFile(notesPath, 'notes');
    await fs.writeFile(
      path.join(home, 'tokens.json'),
      JSON.stringify({ access_token: 'cached', token_type: 'Bearer' })
    );

    await clearOAuthCaches(mkDef('jail-home', home), undefined, 'all');

    await expect(fs.readFile(canaryPath, 'utf8')).resolves.toBe('keep-home');
    await expect(fs.readFile(notesPath, 'utf8')).resolves.toBe('notes');
    await expect(fs.stat(home).then((stat) => stat.isDirectory())).resolves.toBe(true);
    await expect(fs.access(path.join(home, 'tokens.json'))).rejects.toThrow();
  });

  it('does not wipe a fake home when tokenCacheDir is ~', async () => {
    const home = await isolateHome();
    const canaryPath = path.join(home, 'IMPORTANT.txt');
    await fs.writeFile(canaryPath, 'keep-tilde');
    await fs.writeFile(
      path.join(home, 'tokens.json'),
      JSON.stringify({ access_token: 'cached', token_type: 'Bearer' })
    );

    // Config import / normalizePath only expands ~; callers then pass the home path.
    const tokenCacheDir = expandHome('~', home);
    expect(tokenCacheDir).toBe(home);

    await clearOAuthCaches(mkDef('jail-tilde', tokenCacheDir), undefined, 'all');

    await expect(fs.readFile(canaryPath, 'utf8')).resolves.toBe('keep-tilde');
    await expect(fs.stat(home).then((stat) => stat.isDirectory())).resolves.toBe(true);
    await expect(fs.access(path.join(home, 'tokens.json'))).rejects.toThrow();
  });
});

import { describe, expect, it } from 'vitest';
import { isStoredOAuthClientInformation, isStoredOAuthTokens } from '../src/oauth-credential-validation.js';

function validTokens(overrides: Record<string, unknown> = {}): unknown {
  return { access_token: 'tok', token_type: 'bearer', ...overrides };
}

describe('isStoredOAuthTokens', () => {
  it('accepts the minimal required shape', () => {
    expect(isStoredOAuthTokens(validTokens())).toBe(true);
  });

  it('accepts every optional field at its valid type', () => {
    expect(
      isStoredOAuthTokens(
        validTokens({
          refresh_token: 'refresh',
          scope: 'read write',
          issuer: 'https://issuer.example',
          expires_in: 3600,
          expires_at: 1_700_000_000,
          expiresAt: 1_700_000_000,
        })
      )
    ).toBe(true);
  });

  it('rejects non-record inputs', () => {
    expect(isStoredOAuthTokens(null)).toBe(false);
    expect(isStoredOAuthTokens(undefined)).toBe(false);
    expect(isStoredOAuthTokens('bearer')).toBe(false);
    expect(isStoredOAuthTokens(42)).toBe(false);
    expect(isStoredOAuthTokens(['access_token'])).toBe(false);
  });

  it('rejects a missing, empty, or non-string access_token', () => {
    expect(isStoredOAuthTokens({ token_type: 'bearer' })).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ access_token: '' }))).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ access_token: 123 }))).toBe(false);
  });

  it('rejects a missing, empty, or non-string token_type', () => {
    expect(isStoredOAuthTokens({ access_token: 'tok' })).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ token_type: '' }))).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ token_type: 123 }))).toBe(false);
  });

  it('rejects an optional string field carrying a non-string value', () => {
    expect(isStoredOAuthTokens(validTokens({ refresh_token: 1 }))).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ scope: 1 }))).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ issuer: 1 }))).toBe(false);
  });

  it('rejects an optional numeric field carrying a non-finite or non-number value', () => {
    expect(isStoredOAuthTokens(validTokens({ expires_in: Number.NaN }))).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ expires_in: Number.POSITIVE_INFINITY }))).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ expires_in: '3600' }))).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ expires_at: Number.NaN }))).toBe(false);
    expect(isStoredOAuthTokens(validTokens({ expiresAt: Number.NaN }))).toBe(false);
  });
});

describe('isStoredOAuthClientInformation', () => {
  it('rejects non-record inputs', () => {
    expect(isStoredOAuthClientInformation(null)).toBe(false);
    expect(isStoredOAuthClientInformation('issuer')).toBe(false);
    expect(isStoredOAuthClientInformation(['issuer'])).toBe(false);
  });

  it('accepts a record with no issuer or a string issuer', () => {
    expect(isStoredOAuthClientInformation({})).toBe(true);
    expect(isStoredOAuthClientInformation({ client_id: 'abc' })).toBe(true);
    expect(isStoredOAuthClientInformation({ issuer: 'https://issuer.example' })).toBe(true);
  });

  it('rejects a record whose issuer is present but not a string', () => {
    expect(isStoredOAuthClientInformation({ issuer: 42 })).toBe(false);
  });
});

