const REPO_ROOT = fileURLToPath(new URL('..', import.meta.url));

describe('README protocol claims', () => {
  it('describes legacy compatibility without claiming byte-identical handshakes', async () => {
    const readme = await fs.readFile(path.join(REPO_ROOT, 'README.md'), 'utf8');

    expect(readme).not.toContain('classic `initialize` handshake, byte-identical to before');
    expect(readme).toContain('client elicitation capabilities');
  });

  it('distinguishes representative CI coverage from the full fixture surface', async () => {
    const readme = await fs.readFile(path.join(REPO_ROOT, 'README.md'), 'utf8');

    expect(readme).not.toContain('exercising the wide surface of each protocol generation end-to-end in CI');
    expect(readme).toContain('representative fixture paths end-to-end');
  });
});

import { createHmac, hash, timingSafeEqual } from 'node:crypto';

export const BROWSER_RELAY_AUTH_LABEL = 'openclaw.browser-relay.auth';
export const BROWSER_RELAY_AUTH_VERSION = 2;
export const BROWSER_RELAY_CHALLENGE_MAX_LIFETIME_MS = 10_000;
export const BROWSER_RELAY_CLOCK_SKEW_MS = 30_000;
export const BROWSER_RELAY_AUTH_CHALLENGE_PATH = '/_openclaw/relay/auth/v2/challenge';
export const BROWSER_RELAY_AUTH_COMPLETE_PATH = '/_openclaw/relay/auth/v2/complete';
export const BROWSER_RELAY_CDP_PATH = '/cdp';
export const BROWSER_RELAY_CDP_ROLE = 'cdp';
export const BROWSER_RELAY_CDP_TRANSPORT = 'connection';
export const BROWSER_RELAY_CDP_METHOD = 'SEQUENCE';
export const BROWSER_RELAY_CDP_RESOURCE = '/json/version -> /cdp';
export const BROWSER_RELAY_CDP_FLOW = 'cdp';
export const BROWSER_RELAY_VERSION_PATH = '/json/version';

export type BrowserRelayProofKind = 'server' | 'client' | 'accept';

export interface BrowserRelayProofFields {
  readonly keyId: string;
  readonly instanceId: string;
  readonly sessionId: string;
  readonly clientNonce: string;
  readonly serverNonce: string;
  readonly issuedAtMs: number;
  readonly expiresAtMs: number;
  readonly role: string;
  readonly transport: string;
  readonly method: string;
  readonly resource: string;
  readonly flow: string;
}

export function deriveBrowserRelayKeyId(key: Uint8Array): string {
  assertRelayKey(key);
  // This is a protocol fingerprint of an enforced 256-bit random key, not a
  // password verifier. Keep the frozen v2 bytes shared with relay clients.
  return hash('sha256', key, 'base64url').slice(0, 22);
}

export function canonicalizeBrowserRelayProof(
  proofKind: BrowserRelayProofKind,
  fields: BrowserRelayProofFields,
  clientProof?: string
): Buffer {
  const canonical: Array<string | number> = [
    BROWSER_RELAY_AUTH_LABEL,
    BROWSER_RELAY_AUTH_VERSION,
    proofKind,
    fields.keyId,
    fields.instanceId,
    fields.sessionId,
    fields.clientNonce,
    fields.serverNonce,
    fields.issuedAtMs,
    fields.expiresAtMs,
    fields.role,
    fields.transport,
    fields.method,
    fields.resource,
    fields.flow,
  ];
  if (proofKind === 'accept') {
    if (!clientProof || !isCanonicalBase64Url(clientProof, 32)) {
      throw new Error('Browser relay accept proof requires a 32-byte client proof.');
    }
    canonical.push(clientProof);
  } else if (clientProof !== undefined) {
    throw new Error('Browser relay client proof is only valid for an accept proof.');
  }
  return Buffer.from(JSON.stringify(canonical), 'utf8');
}

export function createBrowserRelayProof(
  key: Uint8Array,
  proofKind: BrowserRelayProofKind,
  fields: BrowserRelayProofFields,
  clientProof?: string
): string {
  assertRelayKey(key);
  return createHmac('sha256', key)
    .update(canonicalizeBrowserRelayProof(proofKind, fields, clientProof))
    .digest('base64url');
}

export function verifyBrowserRelayProof(
  key: Uint8Array,
  proofKind: BrowserRelayProofKind,
  fields: BrowserRelayProofFields,
  proof: string,
  clientProof?: string
): boolean {
  if (!isCanonicalBase64Url(proof, 32)) return false;
  const actual = Buffer.from(proof, 'base64url');
  const expected = Buffer.from(createBrowserRelayProof(key, proofKind, fields, clientProof), 'base64url');
  return actual.byteLength === expected.byteLength && timingSafeEqual(actual, expected);
}

function assertRelayKey(key: Uint8Array): void {
  if (key.byteLength !== 32) throw new Error('Browser relay key must contain 32 bytes.');
}

function isCanonicalBase64Url(value: string, bytes: number): boolean {
  if (!/^[A-Za-z0-9_-]+$/u.test(value)) return false;
  const decoded = Buffer.from(value, 'base64url');
  return decoded.byteLength === bytes && decoded.toString('base64url') === value;
}

import { runtimeEnvironment } from './runtime/environment.js';
const TRUE_VALUES = new Set(['1', 'true', 'yes']);

export function suppressBrowserLaunchFromEnv(env: NodeJS.ProcessEnv = runtimeEnvironment()): boolean {
  const raw = env.MCPORTER_OAUTH_NO_BROWSER;
  return raw !== undefined && TRUE_VALUES.has(raw.trim().toLowerCase());
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

function throwConnectBoom(): never {
  throw new Error('connect boom');
}

const mocks = vi.hoisted(() => {
  const connectMock = vi.fn();
  const listToolsMock = vi.fn();
  const callToolMock = vi.fn();
  const listResourcesMock = vi.fn();
  const readCachedAccessTokenMock = vi.fn();
  const clientInstances: unknown[] = [];
  const streamableInstances: unknown[] = [];
  const stdioInstances: unknown[] = [];

  class MockClient {
    private readonly requestHandlers = new Map<string, unknown>();

    constructor() {
      clientInstances.push(this);
    }

    async connect(transport: { start?: () => Promise<void> }) {
      connectMock(transport);
      if (typeof transport.start === 'function') {
        await transport.start();
      }
    }

    async close() {}

    setRequestHandler(method: string, handler: unknown) {
      this.requestHandlers.set(method, handler);
    }

    async listTools(params: unknown) {
      return listToolsMock(params);
    }

    async callTool(params: unknown) {
      return callToolMock(params);
    }

    async listResources(params: unknown) {
      return listResourcesMock(params);
    }

    async request(request: { method: string; params?: unknown }) {
      if (request.method !== 'resources/list') throw new Error(`Unexpected request method ${request.method}`);
      return listResourcesMock(request.params);
    }
  }

  class MockStreamableHTTPClientTransport {
    public start = vi.fn(async () => {});
    public close = vi.fn(async () => {});
    constructor(
      public url: URL,
      public options?: unknown
    ) {
      streamableInstances.push(this);
    }
  }

  class MockSSEClientTransport {
    public start = vi.fn(async () => {});
    public close = vi.fn(async () => {});
    constructor(
      public url: URL,
      public options?: unknown
    ) {}
  }

  class MockStdioClientTransport {
    public start = vi.fn(async () => {});
    public close = vi.fn(async () => {});
    constructor(public options: unknown) {
      stdioInstances.push(this);
    }
  }

  class MockUnauthorizedError extends Error {}

  return {
    connectMock,
    listToolsMock,
    callToolMock,
    listResourcesMock,
    readCachedAccessTokenMock,
    clientInstances,
    streamableInstances,
    stdioInstances,
    MockClient,
    MockStreamableHTTPClientTransport,
    MockSSEClientTransport,
    MockStdioClientTransport,
    MockUnauthorizedError,
  };
});

vi.mock('@modelcontextprotocol/client', async (importOriginal) => ({
  ...(await importOriginal<typeof import('@modelcontextprotocol/client')>()),
  Client: mocks.MockClient,
  StreamableHTTPClientTransport: mocks.MockStreamableHTTPClientTransport,
  SSEClientTransport: mocks.MockSSEClientTransport,
  UnauthorizedError: mocks.MockUnauthorizedError,
}));

vi.mock('@modelcontextprotocol/client/stdio', async (importOriginal) => ({
  ...(await importOriginal<typeof import('@modelcontextprotocol/client/stdio')>()),
  StdioClientTransport: mocks.MockStdioClientTransport,
}));

vi.mock('../src/oauth-persistence.js', () => ({
  readCachedAccessToken: mocks.readCachedAccessTokenMock,
