import {
  type OAuthClientProvider,
  SSEClientTransport,
  StreamableHTTPClientTransport,
} from '@modelcontextprotocol/client';
import { expect, it, vi } from 'vitest';

it.each(['streamable', 'sse'] as const)(
  '%s correlates a rejected OAuth token when it overrides a configured Authorization header',
  async (kind) => {
    const tokens = { access_token: 'synthetic-oauth-token', token_type: 'Bearer', refresh_token: 'synthetic-refresh' };
    const stopped = new Error('stop after observing the unauthorized request');
    const onUnauthorized = vi.fn<NonNullable<OAuthClientProvider['onOAuthUnauthorized']>>(async () => {
      throw stopped;
    });
    const provider: OAuthClientProvider = {
      redirectUrl: undefined,
      clientMetadata: { redirect_uris: [] },
      clientInformation: () => undefined,
      tokens: () => tokens,
      saveTokens: vi.fn(),
      redirectToAuthorization: vi.fn(),
      saveCodeVerifier: vi.fn(),
      codeVerifier: () => 'synthetic-verifier',
      onOAuthUnauthorized: onUnauthorized,
    };
    const sent: Array<string | null> = [];
    const fetchFn = async (_input: RequestInfo | URL, init?: RequestInit) => {
      sent.push(new Headers(init?.headers).get('authorization'));
      return new Response(null, { status: 401 });
    };
    const options = {
      authProvider: provider,
      requestInit: { headers: { Authorization: 'Bearer synthetic-configured-token' } },
      fetch: fetchFn,
    };
    const endpoint = new URL('https://mcp.example.test/mcp');
    const transport =
      kind === 'sse' ? new SSEClientTransport(endpoint, options) : new StreamableHTTPClientTransport(endpoint, options);
    try {
      const request = async () => {
        await transport.start();
        await transport.send({ jsonrpc: '2.0', method: 'notifications/initialized' });
      };
      await expect(request()).rejects.toBe(stopped);
      expect(sent).toEqual(['Bearer synthetic-oauth-token']);
      expect(onUnauthorized).toHaveBeenCalledExactlyOnceWith(
        expect.objectContaining({ presentedTokens: tokens }),
        expect.any(Function)
      );
    } finally {
      await transport.close();
    }
  }
);

import { afterEach, describe, expect, it, vi } from 'vitest';
import type { OAuthSession } from '../src/oauth.js';
import { OAuthTimeoutError, waitForAuthorizationCodeWithTimeout } from '../src/runtime/oauth.js';

describe('waitForAuthorizationCodeWithTimeout', () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  it('rejects when the authorization code is not received before the timeout', async () => {
    vi.useFakeTimers();
    const session: OAuthSession = {
      provider: {
        waitForAuthorizationCode: vi.fn(),
      } as unknown as OAuthSession['provider'],
      waitForAuthorizationCode: vi.fn(() => new Promise<string>(() => {})),
      close: vi.fn(async () => {}),
    };
    const logger = {
      info: vi.fn(),
      warn: vi.fn(),
      error: vi.fn(),
    };

    const promise = waitForAuthorizationCodeWithTimeout(session, logger, 'fake', 1_000);
    const expectation = expect(promise).rejects.toBeInstanceOf(OAuthTimeoutError);
    await vi.advanceTimersByTimeAsync(1_000);
    await expectation;
    expect(logger.warn).toHaveBeenCalledWith(expect.stringContaining('timed out after 1s'));
  });

  it('resolves when the authorization code arrives before the timeout', async () => {
    vi.useFakeTimers();
    let resolveCode: ((value: string) => void) | undefined;
    const session: OAuthSession = {
      provider: {
        waitForAuthorizationCode: vi.fn(),
      } as unknown as OAuthSession['provider'],
      waitForAuthorizationCode: vi.fn(
        () =>
          new Promise<string>((resolve) => {
            resolveCode = resolve;
          })
      ),
      close: vi.fn(async () => {}),
    };
    const logger = {
      info: vi.fn(),
      warn: vi.fn(),
      error: vi.fn(),
    };

    const promise = waitForAuthorizationCodeWithTimeout(session, logger, 'fake', 1_000);
    const expectation = expect(promise).resolves.toBe('abc123');
    resolveCode?.('abc123');
    await vi.advanceTimersByTimeAsync(0);
    await expectation;
    expect(logger.warn).not.toHaveBeenCalled();
  });
});

import type { ServerDefinition } from './config.js';
import { analyzeConnectionError } from './error-classifier.js';
import type { Logger } from './logging.js';

export function maybeEnableOAuth(definition: ServerDefinition, logger: Logger): ServerDefinition | undefined {
  if (definition.auth === 'oauth' || definition.auth === 'refreshable_bearer') {
    return undefined;
  }
  if (definition.command.kind !== 'http') {
    return undefined;
  }
  // Allow OAuth promotion for any HTTP server that returns 401,
  // not just ad-hoc servers (fixes issue #38)
  logger.info(`Detected OAuth requirement for '${definition.name}'. Launching browser flow...`);
  return {
    ...definition,
    auth: 'oauth',
  };
}

export function isUnauthorizedError(error: unknown): boolean {
  const issue = analyzeConnectionError(error);
  return issue.kind === 'auth';
}

import { privateFixtureDirectory } from './helpers/private-directory.js';
